(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const textOf = (b) => {
    const t = b && b.data && b.data.text;
    if (!t || !t.initialAttributedTexts || !t.initialAttributedTexts.text) return '';
    const obj = t.initialAttributedTexts.text;
    return Object.keys(obj).sort((a,c)=>Number(a)-Number(c)).map(k=>obj[k]).join('');
  };
  const lines = [];
  const walk = (id, depth, inTable) => {
    const b = bm[id];
    if (!b) return;
    const d = b.data || {};
    const type = d.type;
    const txt = textOf(b);
    if (type === 'table') {
      lines.push('\n[TABLE]');
      const rows = {};
      (d.children||[]).forEach(cid => {
        const cell = bm[cid];
        if (!cell) return;
        const cd = cell.data||{};
        // cell children are text blocks
        const cellText = (cd.children||[]).map(x => textOf(bm[x])).filter(Boolean).join(' ');
        // also try text on cell itself
        const self = textOf(cell);
        const content = [self, cellText].filter(Boolean).join(' ');
        // row/col?
        lines.push('CELL|' + (cd.row_index??'?') + '|' + (cd.col_index??'?') + '|' + content);
      });
      lines.push('[/TABLE]');
      return;
    }
    if (type === 'image') { lines.push('[IMAGE]'); return; }
    const prefix = type==='heading1' ? '# ' : type==='heading2' ? '## ' : '';
    if (txt || type==='heading1' || type==='heading2') lines.push(prefix + txt);
    (d.children||[]).forEach(cid => walk(cid, depth+1));
  };
  const root = window.DATA.clientVars.data.id;
  walk(root, 0);
  return lines.join('\n');
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const tables = Object.values(bm).filter(b => b.data && b.data.type==='table');
  const t = tables[0];
  const d = t.data;
  const keys = Object.keys(d);
  const child0 = bm[d.children[0]];
  const cellKeys = Object.keys(child0.data);
  const sampleCells = d.children.slice(0,3).map(id => {
    const c = bm[id].data;
    const kids = (c.children||[]).slice(0,3).map(kid => {
      const kb = bm[kid];
      return {type: kb && kb.data && kb.data.type, keys: kb ? Object.keys(kb.data).slice(0,20) : null, text: kb && kb.data && kb.data.text && kb.data.text.initialAttributedTexts && kb.data.text.initialAttributedTexts.text};
    });
    return {id, type: c.type, row: c.row_index, col: c.col_index, keys: Object.keys(c), kids};
  });
  return {tableKeys: keys, rows: d.rows, cols: d.columns, col_width: d.column_set, childCount: d.children.length, sampleCells, prop: d.property || d.table_info || null};
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const tables = Object.entries(bm).filter(([id,b]) => b.data && b.data.type==='table');
  return tables.map(([id,b]) => {
    const d = b.data;
    return {id, keys: Object.keys(d), childType: d.children && d.children.constructor && d.children.constructor.name, childLen: d.children ? (Array.isArray(d.children)? d.children.length : Object.keys(d.children).length) : null, snapshot: JSON.stringify(d).slice(0,1500)};
  });
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const textOf = (id) => {
    const b = bm[id];
    if (!b) return '';
    const d = b.data || {};
    const t = d.text;
    let self = '';
    if (t && t.initialAttributedTexts && t.initialAttributedTexts.text) {
      const obj = t.initialAttributedTexts.text;
      self = Object.keys(obj).sort((a,c)=>Number(a)-Number(c)).map(k=>obj[k]).join('');
    }
    const kids = (d.children||[]).map(textOf).filter(Boolean);
    return [self, ...kids].filter(Boolean).join('\n');
  };
  const tables = Object.values(bm).filter(b => b.data && b.data.type==='table');
  // order by appearance: walk page children
  const page = bm[window.DATA.clientVars.data.id];
  const order = (page.data.children||[]);
  const out = [];
  const headingOf = (id) => {
    const b = bm[id];
    if (!b) return '';
    const d = b.data||{};
    if (d.type==='heading1' || d.type==='heading2' || d.type==='text') {
      const t = d.text && d.text.initialAttributedTexts && d.text.initialAttributedTexts.text;
      if (!t) return '';
      return Object.values(t).join('');
    }
    return '';
  };
  for (const id of order) {
    const b = bm[id];
    if (!b) continue;
    const d = b.data||{};
    if (d.type==='table') {
      const rows = d.rows_id||[];
      const cols = d.columns_id||[];
      const lines = ['TABLE '+rows.length+'x'+cols.length];
      rows.forEach((r,ri) => {
        const cells = cols.map(c => {
          const cell = d.cell_set[r+c];
          return cell ? textOf(cell.block_id).replace(/\n/g,' / ') : '';
        });
        lines.push(ri+' | '+cells.join(' || '));
      });
      out.push(lines.join('\n'));
    } else if (d.type==='image') {
      out.push('[IMAGE]');
    } else {
      const t = headingOf(id);
      if (t) out.push((d.type==='heading1'?'# ':d.type==='heading2'?'## ':'')+t);
    }
  }
  return out.join('\n\n');
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const revSamples = [];
  let withRev = 0;
  for (const [id,b] of Object.entries(bm)) {
    const revs = (b.data && b.data.revisions) || [];
    if (revs.length) { withRev++; if (revSamples.length<3) revSamples.push({id, type:b.data.type, revs}); }
  }
  const meta = window.DATA.clientVars.data.meta_map;
  return {withRev, revSamples, metaKeys: meta? Object.keys(meta).slice(0,20): null, metaSample: meta? meta[Object.keys(meta)[0]] : null, userMap: window.DATA.clientVars.data.user_map};
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const mentions = [];
  for (const [id,b] of Object.entries(bm)) {
    const apool = b.data && b.data.text && b.data.text.apool;
    if (apool && apool.numToAttrib && Object.keys(apool.numToAttrib).length) {
      const txt = b.data.text.initialAttributedTexts && b.data.text.initialAttributedTexts.text;
      mentions.push({id, type:b.data.type, attrib: apool.numToAttrib, text: txt});
    }
  }
  return {mentionCount: mentions.length, mentions: mentions.slice(0,30), external: window.DATA.clientVars.data.external_mention_url, titles: window.DATA.clientVars.data.mention_page_title};
})()

(() => {
  const bm = window.DATA.clientVars.data.block_map;
  const hits = [];
  for (const [id,b] of Object.entries(bm)) {
    const t = b.data && b.data.text && b.data.text.initialAttributedTexts && b.data.text.initialAttributedTexts.text;
    const s = t ? Object.values(t).join('') : '';
    const ap = b.data && b.data.text && b.data.text.apool && b.data.text.apool.numToAttrib;
    const attrs = ap ? Object.values(ap) : [];
    const interesting = /VIP|扣量|金币|免费|paid|查询表|原始需求|highlight|link/.test(s) || attrs.some(a => a[0]==='textHighlight' || a[0]==='link' || a[0]==='bold');
    if (interesting && s) hits.push({s: s.slice(0,500), attrs});
    if (b.data && b.data.type==='image') hits.push({image: b.data});
  }
  return hits;
})()

